use harbor.signal;

pub fn entries() -> String {
    var rendered: List<String> = [];
    var signals = signal.sequence();
    var i = 0;

    while i < signals.len() {
        let entry = match signals.get(i) {
            Some(Signal.Calm) => "calm",
            Some(Signal.Gale(speed)) => "gale:".concat(other: speed.to_text()),
            Some(Signal.Fog(density)) => "fog:".concat(other: density),
            None => "",
        };
        rendered.push(entry);
        i = i + 1;
    }

    rendered.join(sep: ";")
}

